import React, { useRef, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPersonCircleQuestion, faEarthAmericas } from '@fortawesome/free-solid-svg-icons';
import CustomHook from './CustomHook';

export default function Projects() {
  // keep refs array clean each render
  const divs = useRef([]);
  const scrollTab = useRef();
  divs.current = [];

  const attachRef = (el) => {
    if (el && !divs.current.includes(el)) divs.current.push(el);
  };

  // project data — tidy, multiline summaries and clear fields
  const [listProjects] = useState([
    {
      name: 'BANANA — AI-powered E-commerce Platform',
      summary: [
        'Built a responsive e-commerce web app using MERN (MongoDB, Express, React, Node), Firebase auth and Redux for state management.',
        'Implemented dynamic product listings, cart & wishlist, and real-time search to improve user engagement.',
        'Optimized initial load with lazy loading and introduced dark-mode — improved perceived performance and UX consistency.'
      ],
      role: 'Full-Stack Developer — backend APIs, frontend integration and state management',
      tech: 'React, Redux, Node.js, Express, MongoDB, Firebase, Tailwind CSS',
      image: '/BANANA.PNG',
      alt: 'BANANA e-commerce screenshot'
    },
    {
      name: '3D Slider — Interactive Frontend UI',
      summary: [
        'Designed and implemented a performant 3D image/content slider using modern HTML & CSS transforms.',
        'Focused on smooth animations, accessibility fallback, and mobile responsiveness to create an attractive UI component.'
      ],
      role: 'Frontend Developer — UI/UX and CSS animation',
      tech: 'HTML5, CSS3 (transforms & animations), JavaScript',
      image: '/3DSLIDER.PNG',
      alt: '3D slider demo'
    },
    {
      name: 'Library Management System',
      summary: [
        'Developed full-stack library management solution with role-based access for admins and users.',
        'Built RESTful APIs with Express and MongoDB, and a React frontend with reusable components for search, reservation & user management.',
        'Improved query performance by optimizing indexes and API responses.'
      ],
      role: 'Backend & Frontend — API design and frontend integration',
      tech: 'React, Node.js, Express, MongoDB, Socket.IO (for real-time features)',
      image: '/project2.PNG',
      alt: 'Library management system UI'
    }
  ]);

  // call custom hook (unchanged)
  CustomHook(scrollTab, divs);

  return (
    <section className="projects py-12" ref={scrollTab} aria-label="Projects section">
      <div className="max-w-6xl mx-auto px-4" ref={attachRef}>
        <header className="mb-8" ref={attachRef}>
          <h2 className="text-3xl font-bold">Projects</h2>
          <p className="text-gray-600 mt-2 max-w-2xl">
            Selected projects that showcase full-stack development, UI engineering, and problem-solving.
          </p>
        </header>

        <div className="grid gap-8">
          {listProjects.map((proj, idx) => (
            <article
              key={proj.name + idx}
              className="project-item flex flex-col md:flex-row gap-4 bg-white/5 p-4 rounded-lg border border-gray-800"
              ref={attachRef}
            >
              <div className="project-media w-full md:w-1/3 flex-shrink-0">
                <img
                  src={proj.image}
                  alt={proj.alt}
                  className="w-full h-auto rounded-md object-cover shadow-sm"
                  loading="lazy"
                />
              </div>

              <div className="project-content w-full md:w-2/3">
                <h3 className="text-xl font-semibold">{proj.name}</h3>

                <div className="mt-3 space-y-2">
                  {/* Summary bullets */}
                  <ul className="list-disc list-inside text-gray-300">
                    {proj.summary.map((line, i) => (
                      <li key={i} className="text-sm leading-relaxed">{line}</li>
                    ))}
                  </ul>
                </div>

                <div className="mt-4 grid gap-3 sm:grid-cols-2">
                  <div className="mission flex items-start gap-3">
                    <div className="icon text-blue-400 mt-1" aria-hidden>
                      <FontAwesomeIcon icon={faPersonCircleQuestion} />
                    </div>
                    <div>
                      <h4 className="text-sm font-medium">Role</h4>
                      <div className="text-sm text-gray-300">{proj.role}</div>
                    </div>
                  </div>

                  <div className="tech flex items-start gap-3">
                    <div className="icon text-green-400 mt-1" aria-hidden>
                      <FontAwesomeIcon icon={faEarthAmericas} />
                    </div>
                    <div>
                      <h4 className="text-sm font-medium">Tech Stack</h4>
                      <div className="text-sm text-gray-300">{proj.tech}</div>
                    </div>
                  </div>
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}
